import{_ as t,o as a,c as o,a0 as n}from"./chunks/framework.D4fUSYzX.js";const f=JSON.parse('{"title":"Completion","description":"What happens after a turn settles: the decision in manual mode, the limits in auto mode, held turns, and the handoff limit.","frontmatter":{"title":"Completion","description":"What happens after a turn settles: the decision in manual mode, the limits in auto mode, held turns, and the handoff limit."},"headers":[],"relativePath":"work-flow/completion.md","filePath":"work-flow/completion.md"}'),i={name:"work-flow/completion.md"};function s(r,e,h,d,l,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="completion" tabindex="-1">Completion <a class="header-anchor" href="#completion" aria-label="Permalink to &quot;Completion&quot;">​</a></h1><h2 id="after-a-turn-settles" tabindex="-1">After a turn settles <a class="header-anchor" href="#after-a-turn-settles" aria-label="Permalink to &quot;After a turn settles&quot;">​</a></h2><p>When the agent settles its turn, the ticket moves to <code>awaiting</code>, and the handoff&#39;s facts are recorded with the turn: the task type, the agent, its settings, the completion time, the agent&#39;s last message, and the decision that ends the awaiting state. What happens next depends on your mode:</p><ul><li><strong>Manual mode</strong> gives you the decision. Enter opens the <a href="./../operation/modals.html">decision modal</a>: the turn log, and the rows - close the cycle, or hand the ticket off to the next kind of work when the settled turn&#39;s labels offer one.</li><li><strong>Auto mode</strong> decides within the configured limits. A transition marked <code>auto-advance</code> routes the ticket to the next kind of work without you; a turn the machine cannot route closes the cycle. <a href="./../configuration/">The Configuration page</a> marks which of your transitions auto-advance.</li><li>A turn that ended in a failure is never decided for you, in either mode: see held turns below.</li></ul><h2 id="held-turns-and-the-dispatch-pause" tabindex="-1">Held turns and the dispatch pause <a class="header-anchor" href="#held-turns-and-the-dispatch-pause" aria-label="Permalink to &quot;Held turns and the dispatch pause&quot;">​</a></h2><p>A turn that ended in a failure - an error, an interruption, or a cutoff - rests <code>awaiting</code> and shown held until you decide it. While it is held, the factory will not close its cycle and will not route it, in auto mode or manual mode.</p><p>A failed turn also pauses the automatic starts: while the pause stands, auto mode starts no agent by itself, so the factory does not pile more work on top of a failure. The pause ends when you decide the held turn, or when a later turn completes. Your own manual handoffs are never blocked by it, and a start that already stands in the Work queue still takes its seat.</p><p>A missing agent behaves the same way in auto mode: the factory restarts the handoff once, with the last message as the previous message, and at the per-ticket handoff limit it abandons the cycle instead. In manual mode the factory never touches a missing agent: the <code>missing</code> badge stays until you restart or abandon it from the <a href="./../operation/modals.html">missing modal</a>.</p><h2 id="the-per-ticket-handoff-limit" tabindex="-1">The per-ticket handoff limit <a class="header-anchor" href="#the-per-ticket-handoff-limit" aria-label="Permalink to &quot;The per-ticket handoff limit&quot;">​</a></h2><p>Every ticket carries a handoff limit, <code>max-handoffs-per-ticket</code> in the config (10 by default). The limit stops the close-and-rehandoff loop: when a ticket&#39;s started handoffs reach it, auto mode stops dispatching the ticket and leaves it open for you. A manual handoff may still pass the limit, so you keep the last word on one ticket.</p>',10)])])}const m=t(i,[["render",s]]);export{f as __pageData,m as default};
